// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Registrarse Crear una cuenta de cliente y entrar
	// (POST /api/v1/registro)
	Registrarse(ctx context.Context, request RegistrarseRequestObject) (RegistrarseResponseObject, error)
	// Salir Salir
	// (DELETE /api/v1/sesion)
	Salir(ctx context.Context, request SalirRequestObject) (SalirResponseObject, error)
	// VerSesion Quién pide
	// (GET /api/v1/sesion)
	VerSesion(ctx context.Context, request VerSesionRequestObject) (VerSesionResponseObject, error)
	// Entrar Entrar con correo y clave
	// (POST /api/v1/sesion)
	Entrar(ctx context.Context, request EntrarRequestObject) (EntrarResponseObject, error)
	// EstadoDeClave Si la cuenta tiene clave y si se puede poner sin la actual
	// (GET /api/v1/sesion/clave)
	EstadoDeClave(ctx context.Context, request EstadoDeClaveRequestObject) (EstadoDeClaveResponseObject, error)
	// CambiarClave Cambiar la clave (cierra las otras sesiones)
	// (PUT /api/v1/sesion/clave)
	CambiarClave(ctx context.Context, request CambiarClaveRequestObject) (CambiarClaveResponseObject, error)
	// EntrarConEnlace Entrar con un link mágico (un solo uso)
	// (POST /api/v1/sesion/enlace)
	EntrarConEnlace(ctx context.Context, request EntrarConEnlaceRequestObject) (EntrarConEnlaceResponseObject, error)
	// PedirEnlace Manda un link de ingreso al correo, si tiene cuenta (contesta igual si no)
	// (POST /api/v1/sesion/enlace/pedir)
	PedirEnlace(ctx context.Context, request PedirEnlaceRequestObject) (PedirEnlaceResponseObject, error)
	// CargarPin El PIN con que un administrador autoriza en el mostrador (pide la clave de la cuenta)
	// (PUT /api/v1/sesion/pin)
	CargarPin(ctx context.Context, request CargarPinRequestObject) (CargarPinResponseObject, error)
	// DestrabarPin Borra los topes de errores del PIN de autorización (pide la clave de la cuenta)
	// (POST /api/v1/sesion/pin/destrabar)
	DestrabarPin(ctx context.Context, request DestrabarPinRequestObject) (DestrabarPinResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

